-- Alta de Brainnetome Atlas (Fan et al., 2016, Cerebral Cortex) --
-- especie, atlas, sus 246 regiones y sus 246 coordenadas
-- representativas. Generado por scripts/register_brainnetome_atlas.py
-- a partir de los archivos .nii.gz/.xlsx reales (Fase 3/4).
-- Requiere dataset.human.brainnetome.bna_246 ya registrado
-- (register_dataset_brainnetome.sql).

  'species.human.ncbi-taxonomy.9606', 'Ser humano', 'Homo sapiens'
)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, scientific_name = EXCLUDED.scientific_name;

  'atlas.human.brainnetome.bna_246', 'Brainnetome Atlas (Fan et al., 2016, Cerebral Cortex)', 'species.human.ncbi-taxonomy.9606', NULL
)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, version = EXCLUDED.version;

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, atlas_id = EXCLUDED.atlas_id, synonyms = EXCLUDED.synonyms;

ON CONFLICT (id) DO UPDATE SET x = EXCLUDED.x, y = EXCLUDED.y, z = EXCLUDED.z, reference_space = EXCLUDED.reference_space;
